"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["16973"],{91156(e){e.exports=JSON.parse('{"id":"FIN-029","slug":"financial-independence","term":"Financial Independence","also_known_as":[],"difficulty":"Beginner","definition":"Financial independence is having enough income from savings, investments or other sources to cover your living costs without needing to work for money.","explanation":["Reaching financial independence means work becomes a choice rather than a necessity. The money needed to live comes from assets you own, such as investments, rental property or pensions.","A common way to estimate the amount needed is to compare annual spending with the income your investments can safely provide. One widely discussed rule of thumb suggests that withdrawing around 4% of a diversified portfolio each year may be sustainable for many years. On that basis, someone who spends 40,000 a year would need roughly 1 million invested. This is a rough guide, not a guarantee, because future returns and inflation are uncertain.","Two levers decide how quickly someone can get there: how much they save and how much they spend. A higher saving rate both adds to investments faster and lowers the amount needed, because lower spending means less income is required.","Financial independence is a personal target, not a single number. It depends on lifestyle, location, health costs, family needs and how much certainty a person wants. Many people aim for partial independence, where investment income covers some costs and part-time work covers the rest."],"note":"","total":1500,"prev":{"slug":"financial-inclusion","term":"Financial Inclusion"},"next":{"slug":"financial-kpi","term":"Financial KPI"}}')}}]);